sourceScripts.Move_Connected:
(if ((eq #move #this)
     (block 
          (WASetOnMat #target 1)
          (sett Done (eq (WAGetHandCount #target) 0))
          (sett NumDitched 0)
          (loop (not Done)
                (block 
                     (sett Ditch (WARandom 1 (WAGetHandCount #target)))
                     (sett Card (item (WAGetHand #target) Ditch))
                     (WAMessage (WAGetOwner #target) (WAGetName #this) "has forced you to ditch" (WAGetName Card))
                     (WADitchPage #target (subtract Ditch 1))
                     (sett NumDitched (add NumDitched 1))
                     (if ((eq NumDitched 2)
                          (sett Done True)
                         )
                         (True
                          (sett Done (eq (WAGetHandCount #target) 0))
                         )
                     )
                )
          )
          True
     )
    )
    (True True)
)

originalScripts.Move_Connected:
(if ((and (WAIsConnectedDamageSpecial #superstar #this)
          (WAIsOfType #move Impact)
          (not (WAHasModifier #move "Finisher"))
     )
     (WAStun #target #this 2)
    )
)

originalScripts.Page_Played:
(if ((eq #page #this)
     (block 
          (WASetValue (WAGetPlayedBy #this) Stunned_For_Turns 0)
          True
     )
    )
    (True True)
)

originalScripts.Can_Stun:
(if ((eq (WAGetPlayedBy #this) #superstar)
     (block 
          (WAMessage -1 "Lawler: It looks like" (WAGetName #superstar) "shrugged off that move!")
          (WAOutOfPlay #this)
          Nil
     )
    )
    (True True)
)

originalScripts.Move_Connected:
(if ((eq #move #this)
     (block 
          (sett KN (WAGetValue #superstar Knowledge_Momentum))
          (if ((greater-eq KN 1)
               (WADrawPage #superstar)
              )
          )
          (sett Tech (WAGetValue #superstar Technical_Momentum))
          (if ((greater-eq Tech 1)
               (block 
                    (sett NextMom 0)
                    (sett OppPlaybook (WAGetPlaybook #target))
                    (sett Index (count OppPlaybook))
                    (loop (greater Index 0)
                          (block 
                               (sett TempPage (WACreatePageByUNID #target (item OppPlaybook Index)))
                               (if ((WAIsMomentum TempPage)
                                    (sett NextMom Index)
                                   )
                               )
                               (sett Index (subtract Index 1))
                          )
                    )
                    (if ((not (eq NextMom 0))
                         (WADitchFromPlaybook #target (subtract NextMom 1))
                        )
                    )
               )
              )
          )
     )
    )
    (True True)
)

(if ((eq #move #this)
     (block 
          (sett PlayedDamageSpecial 0)
          (enum (WAGetInPlay #superstar) InPlay
                (if ((and (WAIsDamageSpecial InPlay)
                          (eq (WAGetTurn)
                              (WAGetTurnPlayedOn InPlay)
                          )
                     )
                     (sett PlayedDamageSpecial 1)
                    )
                )
          )
          (if ((eq PlayedDamageSpecial 1)
               (block 
                    (sett Specialindices '())
                    (sett Index 0)
                    (WAEnumPlaybook 
                         #superstar
                         Page
                         '(block 
                              (if ((WAIsDamageSpecial Page)
                                   (sett Specialindices (cons Specialindices Index))
                                  )
                              )
                              (sett Index (add Index 1))
                         )
                    )
                    (if ((greater (count Specialindices) 0)
                         (block 
                              (sett PageToDraw (item Specialindices
                                                     (WARandom 1 (count Specialindices))
                                               )
                              )
                              (WADrawPage #superstar PageToDraw)
                         )
                        )
                        (true
                         (WAMessage (WAGetOwner #superstar) "Lawler: There are no Damage Specials left in your playbook!")
                        )
                    )
               )
              )
          )
     )
    )
)

originalScripts.Page_Played:
(if ((eq #page #this)
     (block 
          (sett HandSpecials 0)
          (enum (WAGetHand #initiator) MySpecial
                (if ((WAIsSpecial MySpecial)
                     (sett HandSpecials (add HandSpecials 1))
                    )
                )
          )
          (enum (WAGetHand #target) OppSpecial
                (if ((WAIsSpecial OppSpecial)
                     (sett HandSpecials (add HandSpecials 1))
                    )
                )
          )
          (sett HandSpecials (multiply HandSpecials 2))
          (if ((greater HandSpecials 12)
               (sett HandSpecials 12)
              )
          )
          (WASetValue #this Bonus HandSpecials)
     )
    )
)

originalScripts.Move_Connected:
(if ((eq #move (WAGetValue #this '$RunInMove))
