originalScripts.Move_Connected:
(if ((eq #move #this)
     (block 
          (WAMessage -1 "Jim Ross: The Dudleyz hit with 3D! This one is over!")
          (sett RefInPlay 0)
          (enum (WAPagesInPlay) IsRef
                (if ((and (WAIsSpecial IsRef)
                          (WAHasModifier IsRef 'Referee)
                     )
                     (sett RefInPlay 1)
                    )
                )
          )
          (if ((eq RefInPlay 1)
               (WAWarn #superstar 10)
              )
          )
     )
    )
)

(if ((eq #move #this)
     (block 
          (sett Ditched 0)
          (sett TheHand (WAGetHand #superstar))
          (sett Index (count TheHand))
          (sett DummyPage (WACreatePageByUNID #superstar (WAStringGetValue #this User_Data)))
          (sett DitchUNID (WAGetUNID DummyPage))
          (loop (greater Index 0)
                (block 
                     (if ((and (eq (WAGetUNID (item TheHand index))
                                   DitchUNID
                               )
                               (eq Ditched 0)
                          )
                          (block 
                               (sett Ditched 1)
                               (WADitchPage #superstar (subtract Index 1))
                          )
