          )
     )
     (WASetValue #target AffectPinScore (subtract (WAGetValue #target AffectPinScore) 7))
    )
)

originalScripts.Can_Be_Played:
(if ((eq #page #this)
     (and (not (eq (WAGetValue (WAGameMap) TookAHugeChance)
                   1
               )
          )
          (not (eq (WAGetValue (WAGameMap) EventsPlayed)
                   3
               )
          )
          (or (eq (WAGetLocation #initiator)
                  (WAFindLocation '$Ringside)
              )
              (WAHasModifier (WAGameMap) '$HardcoreMatch)
              (WAHasModifier (WAGameMap) '$LadderMatch)
          )
     )
    )
    ((eq #initiator (WAGetPlayedOn #this))
     (block 
          (sett CanPlay (not (eq (WAGetValue #this Active) 1)))
          (if ((eq (WAGetName #page) "Dodge")
               (sett CanPlay True)
              )
          )
          CanPlay
     )
    )
    (True True)
)

originalScripts.Page_Played:
(if ((and (WAIsMove #page)
          (eq #initiator (WAGetPlayedBy #this))
          (WAHasValue #page "Move_Type" "high risk")
     )
     (block 
          (WADamage #initiator 8)
          (WASetValue #this Active 1)
          (WASetValue (WAGameMap) TookAHugeChance 1)
          (WASetValue 
               (WAGameMap)
               EventsPlayed
               (add 1
                    (WAGetValue (WAGameMap) EventsPlayed)
               )
          )
     )
    )
    ((eq #page #this)
     (block 
          (sett RandCmt (WARandom 1 3))
          (if ((eq RandCmt 1)
               (WAMessage -1 "Jim Ross:" (WAGetName #initiator) "is taking a huge chance!")
              )
              ((eq RandCmt 2)
               (WAMessage -1 "Jim Ross: No," (cat (WAGetName #initiator) ",") "don't do it!")
              )
              ((eq RandCmt 3)
               (block 
                    (if ((WAHasModifier #initiator '$Female)
                         (sett Pronoun "she")
                        )
                        ((WAHasModifier #initiator '$Neuter)
                         (sett Pronoun "it")
                        )
                        (True
                         (sett Pronoun "he")
                        )
                    )
                    (WAMessage -1 "Jim Ross: By God, how high up is" (cat Pronoun "?") "It's got to be at least 20 feet in the air!")
               )
              )
          )
     )
    )
)

