                        )
                        ((WAHasModifier #superstar '$Neuter)
                         (sett ThugPronoun "It's")
                        )
                        (True
                         (sett ThugPronoun "He's")
                        )
                    )
                    (if ((WAHasModifier #target '$Female)
                         (sett VictimPronoun "her")
                        )
                        ((WAHasModifier #target '$Neuter)
                         (sett VictimPronoun "it")
                        )
                        (True
                         (sett VictimPronoun "him")
                        )
                    )
                    (WAMessage -1 "Jim Ross:" ThugPronoun "got" VictimPronoun "hooked up tight!")
                    (WAPinSuperstar #superstar #target 1)
               )
              )
          )
          True
     )
    )
    (True True)
)

originalScripts.Can_Be_Played:
(if ((eq #page #this)
     (if ((and (not (WAIsStunned #initiator))
               (not (WAPlayedRulebreaker #initiator))
          )
          (block 
               (sett CanPlay Nil)
               (sett BaseUNID (WAGetBaseUNID #this))
               (enum (WAPagesInPlay) InPlay
                     (if ((eq (WAGetBaseUNID InPlay) 168)
                          (sett CanPlay True)
                         )
                     )
               )
               (if ((not CanPlay)
                    (block 
                         (if ((WAInSubmissionHold #initiator)
                              (block 
                                   (sett InHold (WAGetInHold #initiator))
                                   (if ((not (eq InHold 0))
                                        (sett CanPlay (WAIsOfType InHold Illegal))
                                       )
                                   )
                              )
                             )
                             (True
                              (if ((and (not (eq (WAGetOpponent #initiator) 0))
                                        (not (eq (WAGetProposedMove (WAGetOpponent #initiator))
                                                 0
                                             )
                                        )
                                   )
                                   (sett CanPlay (WAIsOfType (WAGetProposedMove (WAGetOpponent #initiator)) Illegal))
                                  )
                              )
                             )
                         )
                    )
                   )
               )
               (enum (WAPagesInPlay) Page
                     (if ((eq (WAGetName Page) "Ref Bump")
                          (sett CanPlay Nil)
                         )
                     )
               )
               CanPlay
          )
         )
     )
    )
    (True True)
)

(if ((eq #page #this)
     (if ((not (eq (WAGetOpponent #initiator) 0))
          (if ((and (eq (WAGetOpponent #initiator) #target)
                    (not (eq (WAHasControl)
