                    (sett PropMove (WAGetProposedMove #target))
                    (enum (WAGetConnectedMoves (WAGetOpponent #initiator)) ConnMove
                          (if ((eq (WAGetName ConnMove)
                                   (WAGetName PropMove)
                               )
                               (sett CanPlay True)
                              )
                          )
                    )
                    CanPlay
               )
              )
              (True Nil)
          )
         )
         (True Nil)
     )
    )
    (True True)
)

(if ((eq #page #this)
     (if ((not (eq (WAGetOpponent #initiator) 0))
          (if ((and (eq (WAGetOpponent #initiator) #target)
                    (not (eq (WAHasControl)
                             (WAGetOwner #initiator)
                         )
                    )
                    (not (WAInSubmissionHold #initiator))
               )
               (block 
                    (sett CanPlay Nil)
                    (sett PropMove (WAGetProposedMove #target))
                    (enum (WAGetConnectedMoves (WAGetOpponent #initiator)) ConnMove
                          (if ((eq (WAGetName ConnMove)
                                   (WAGetName PropMove)
                               )
                               (sett CanPlay True)
                              )
                          )
                    )
                    CanPlay
               )
              )
              (True Nil)
          )
         )
         (True Nil)
     )
    )
    (True True)
)

