(if ((eq #move #this)
     (block 
          (WASetOnMat #target 1)
          (WAPinSuperstar #superstar #target 1)
          (if ((greater (WAGetValue #superstar PinAttempts) (WAGetValue #target PinAttempts))
               (block 
                    (WASetValue #superstar Generic_Momentum (add 1 (WAGetValue #superstar Generic_Momentum)))
